@pytest.mark.parametrize('name,a,m,d,f,c,exp', V, ids=[x[0] for x in V])
def test_damage(name, a, m, d, f, c, exp):
    assert tuple(damage_calc(a, m, d, f, c)) == tuple(exp)
def test_override():
    A={'id':'garchomp','nature':'jolly','evs':{'atk':252}}; H={'id':'heatran','evs':{'hp':252}}
    assert tuple(damage_calc(A,'earthquake',H,None,False,100)) == (624,736)
    assert tuple(damage_calc(A,'earthquake',H,None,False,50)) != (624,736)
def test_zero_bp_raises():
    with pytest.raises(ValueError):
        damage_calc({'id':'garchomp'}, 'lowkick', {'id':'heatran'})
